"""Derive school calendar and device branches from independently sealed facts."""

from datetime import datetime, timedelta

HASH_FIELDS = {
    "calendar_source_sha256": "school_calendar",
    "operation_source_sha256": "operation_hours",
    "class_source_sha256": "class_hours",
    "clock_source_sha256": "civil_date_time",
    "beacon_designation_source_sha256": "beacon_designation",
    "beacon_configuration_source_sha256": "beacon_lamp_configuration",
    "beacon_history_source_sha256": "beacon_lamp_history",
    "sign_source_sha256": "sign_active_period",
}


def instant(value, name):
    if not isinstance(value, str):
        raise ValueError("source-bound timestamp missing: " + name)
    try:
        result = datetime.fromisoformat(value)
    except ValueError as exc:
        raise ValueError("valid source-bound timestamp required: " + name) from exc
    if result.tzinfo is None or result.utcoffset() is None:
        raise ValueError("offset-aware source-bound timestamp required: " + name)
    return result


def derive(packet, records):
    if not isinstance(packet, dict) or packet.get("source_kind") != "original_school_clock_and_device":
        raise ValueError("original independent school clock/device packet required")
    for field, name in HASH_FIELDS.items():
        if packet.get(field) != records[name]["sha256"]:
            raise ValueError("independent source hash mismatch: " + name)
    now = instant(packet.get("local_datetime"), "local clock")
    end = instant(packet.get("operation_end_local"), "operation end")
    next_start = instant(packet.get("next_operation_start_local"), "next start")
    class_start = instant(packet.get("class_start_local"), "class start")
    class_end = instant(packet.get("class_end_local"), "class end")
    if not end < next_start or not class_start < class_end:
        raise ValueError("original school schedule ordering invalid")
    for name in ("school_in_session_today", "operational_beacon_designation",
                 "sign_limit_active", "beacon_alternating_capable"):
        if type(packet.get(name)) is not bool:
            raise ValueError("original independent school/device fact missing: " + name)
    count = packet.get("beacon_yellow_lamp_count")
    if type(count) is not int or count < 0:
        raise ValueError("original beacon lamp count required")
    history = packet.get("beacon_lamp_history")
    if not isinstance(history, list) or len(history) < 4 or any(
            not isinstance(row, list) or len(row) != count or any(type(v) is not bool for v in row)
            for row in history):
        raise ValueError("original per-lamp history required")
    alternating_observed = count >= 2 and all(sum(row) == 1 for row in history) and all(
        history[i] != history[i - 1] for i in range(1, len(history)))
    outside_operation = end + timedelta(minutes=30) <= now <= next_start - timedelta(minutes=30)
    return {
        "school_in_session_today": packet["school_in_session_today"],
        "after_operation_half_hour": end + timedelta(minutes=30) <= now < next_start,
        "before_next_start_half_hour": end < now <= next_start - timedelta(minutes=30),
        "near_after_operation_boundary": end + timedelta(minutes=30) <= now < end + timedelta(minutes=60),
        "near_before_next_start_boundary": next_start - timedelta(minutes=60) < now <= next_start - timedelta(minutes=30),
        "outside_operation_half_hour": outside_operation,
        "during_class": class_start <= now <= class_end,
        "operational_beacon_designation": packet["operational_beacon_designation"],
        "beacon_definition_supported": count >= 2 and packet["beacon_alternating_capable"],
        "alternating_flash_observed": alternating_observed,
        "sign_limit_active": packet["sign_limit_active"],
        "source_limit": "Derived source facts do not alone resolve statutory applicability or physical validity",
    }

"""Source-bound bus speed, school-zone and device observations for NRS 484B.363(1)."""

import argparse
import hashlib
import json
import math
from pathlib import Path

ASSIGNMENT_ID = "testing__C262661__NRS-484B-363-1__bus_driver"


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def measure(case_id, context_path, trace_path, receipt_path):
    if not case_id.startswith(ASSIGNMENT_ID + "__"):
        raise ValueError("exact assignment case required")
    receipt = json.loads(Path(receipt_path).read_text(encoding="utf-8"))
    if (receipt.get("assignment_id"), receipt.get("case_id")) != (ASSIGNMENT_ID, case_id):
        raise ValueError("original source receipt identity mismatch")
    if receipt.get("diagnostic_fixture") or receipt.get("source_kind") != "original_native_capture":
        raise ValueError("original Native capture required")
    if receipt.get("context_sha256") != sha(context_path) or receipt.get("trace_sha256") != sha(trace_path):
        raise ValueError("original source bytes changed")
    context = json.loads(Path(context_path).read_text(encoding="utf-8"))
    if context.get("case_id") != case_id or not isinstance(context.get("map_sha256"), str) or len(context["map_sha256"]) != 64:
        raise ValueError("exact source map context required")
    for key in ("zone_designation_source", "zone_boundaries_source", "school_property_source",
                "bus_route_source", "bus_blueprint_source", "driver_identity_source", "children_locations_source",
                "civil_date_time_source", "school_calendar_source", "operation_hours_source",
                "class_hours_source", "beacon_designation_source", "beacon_operability_source",
                "beacon_lamp_configuration_source", "beacon_lamp_history_source", "sign_active_period_source"):
        if not context.get(key):
            raise ValueError("original context source missing: " + key)
    for key in ("local_datetime", "operation_end_local", "next_operation_start_local",
                "class_start_local", "class_end_local"):
        if not isinstance(context.get(key), str) or not context[key]:
            raise ValueError("independent original school timing missing: " + key)
    if type(context.get("school_in_session_today")) is not bool or type(context.get("operational_beacon_designation")) is not bool:
        raise ValueError("independent session and beacon designation facts required")
    rows = [json.loads(line) for line in Path(trace_path).read_text(encoding="utf-8").splitlines() if line]
    if len(rows) < 2 or len(rows) != receipt.get("frame_count") or receipt.get("fps") != 20:
        raise ValueError("original 20 Hz frame count mismatch")
    observations = []
    for index, row in enumerate(rows):
        if row.get("frame") != index or not isinstance(row.get("time_s"), (int, float)) or abs(row["time_s"] - index / 20) > .002:
            raise ValueError("original frame cadence mismatch")
        speed = row.get("bus_speed_mps")
        if not isinstance(speed, (int, float)) or not math.isfinite(speed) or speed < 0:
            raise ValueError("original bus speed required")
        if type(row.get("inside_designated_zone")) is not bool:
            raise ValueError("original zone membership required")
        lights = row.get("beacon_yellow_lights_lit")
        if not isinstance(lights, list) or any(type(x) is not bool for x in lights):
            raise ValueError("independent original yellow lamp states required")
        if type(row.get("sign_limit_active")) is not bool:
            raise ValueError("original sign-active observation required")
        children = row.get("children_actor_ids")
        if not isinstance(children, list) or any(not isinstance(x, str) or not x for x in children):
            raise ValueError("original children inventory required")
        observations.append({"frame": index, "time_s": row["time_s"],
                             "bus_speed_mps": speed, "bus_speed_mph": speed * 2.2369362921,
                             "inside_designated_zone": row["inside_designated_zone"],
                             "beacon_yellow_lights_lit": lights,
                             "sign_limit_active": row["sign_limit_active"],
                             "children_actor_ids": children})
    return {"assignment_id": ASSIGNMENT_ID, "case_id": case_id,
            "source_bindings": {"context_sha256": sha(context_path), "trace_sha256": sha(trace_path),
                                "receipt_sha256": sha(receipt_path), "native_map_sha256": context["map_sha256"]},
            "school_in_session_today_source_fact": context["school_in_session_today"],
            "operational_beacon_designation_source_fact": context["operational_beacon_designation"],
            "school_timing_source_facts": {k: context[k] for k in ("local_datetime", "operation_end_local",
                                    "next_operation_start_local", "class_start_local", "class_end_local")},
            "fifteen_mph_reference_only": 15, "half_hour_reference_minutes_only": 30,
            "maximum_observed_inside_zone_mph": max((x["bus_speed_mph"] for x in observations if x["inside_designated_zone"]), default=None),
            "observations": observations, "exception_judgment": "unresolved",
            "beacon_definition_judgment": "unresolved", "speed_rule_judgment": "unresolved",
            "physical_acceptance": "unverified"}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    for name in ("case", "context", "trace", "receipt", "output"):
        parser.add_argument("--" + name, required=True)
    args = parser.parse_args()
    result = measure(args.case, args.context, args.trace, args.receipt)
    Path(args.output).write_text(json.dumps(result, indent=2, sort_keys=True) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
